DECLARE @ID_e3a519eb36d8 UNIQUEIDENTIFIER,
@EntityActionID_e3a519eb36d8 UNIQUEIDENTIFIER,
@ActionFilterID_e3a519eb36d8 UNIQUEIDENTIFIER,
@Sequence_e3a519eb36d8 INT,
@Status_e3a519eb36d8 NVARCHAR(20)
SET
  @ID_e3a519eb36d8 = '7B4E2D18-5F39-4A81-8C62-9D1E4F7A2B30'
SET
  @EntityActionID_e3a519eb36d8 = '90365AD6-79C4-44EB-A474-AF2C96AC2D9F'
SET
  @ActionFilterID_e3a519eb36d8 = '4A91F2E3-8C47-4D62-9B15-7E2A3C4D5F60'
SET
  @Sequence_e3a519eb36d8 = 1
SET
  @Status_e3a519eb36d8 = N'Active'
-- The Order Confirmed -> Send Document binding (shipped in an earlier seed), its ID first, then by
-- entity and action; the filter, its ID first, then by its description.
SELECT TOP 1 @EntityActionID_e3a519eb36d8 = ea.[ID] FROM [${mjSchema}].[EntityAction] ea
    JOIN [${mjSchema}].[Entity] e ON e.[ID] = ea.[EntityID] JOIN [${mjSchema}].[Action] a ON a.[ID] = ea.[ActionID]
    WHERE ea.[ID] = @EntityActionID_e3a519eb36d8 OR (e.[Name] = N'MJ_BizApps_Orders: Order Headers' AND a.[Name] = N'Send Document')
    ORDER BY CASE WHEN ea.[ID] = @EntityActionID_e3a519eb36d8 THEN 0 ELSE 1 END
SELECT TOP 1 @ActionFilterID_e3a519eb36d8 = [ID] FROM [${mjSchema}].[ActionFilter]
    WHERE [ID] = @ActionFilterID_e3a519eb36d8 OR [UserDescription] = N'MJ_BizApps_Orders: Order Status Changed To Confirmed. True when the save transitions OrderHeader.Status to Confirmed.'
    ORDER BY CASE WHEN [ID] = @ActionFilterID_e3a519eb36d8 THEN 0 ELSE 1 END
IF EXISTS (SELECT 1 FROM [${mjSchema}].[EntityAction] WHERE [ID] = @EntityActionID_e3a519eb36d8)
   AND EXISTS (SELECT 1 FROM [${mjSchema}].[ActionFilter] WHERE [ID] = @ActionFilterID_e3a519eb36d8)
   AND NOT EXISTS (SELECT 1 FROM [${mjSchema}].[EntityActionFilter]
               WHERE [ID] = @ID_e3a519eb36d8
                  OR ([EntityActionID] = @EntityActionID_e3a519eb36d8 AND [ActionFilterID] = @ActionFilterID_e3a519eb36d8))
BEGIN
EXEC [${mjSchema}].spCreateEntityActionFilter @ID = @ID_e3a519eb36d8,
  @EntityActionID = @EntityActionID_e3a519eb36d8,
  @ActionFilterID = @ActionFilterID_e3a519eb36d8,
  @Sequence = @Sequence_e3a519eb36d8,
  @Status = @Status_e3a519eb36d8
END;

GO

